    互不冲突；静态用户唯一、静态前缀不重复，保留集与静态集不交。
    """
    if not isinstance(pool, tuple):
        raise TypeError(f"v6 pool must be a tuple, got {type(pool).__name__}")
    if len(pool) != 4:
        raise ValueError(
            f"v6 pool must be a 4-tuple (cidr, deleg_len, reserved, static), "
            f"got {len(pool)} items"
